package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for StdDateFormat#isLenient
 */
public class StdDateFormat_isLenient_TriageGen1Test {

    @Test
    public void testIsLenient_DefaultValue() {
        // When _lenient is null, it should return true
        StdDateFormat df = new StdDateFormat();
        assertTrue("Default isLenient should be true when _lenient is null", df.isLenient());
    }

    @Test
    public void testIsLenient_True() {
        // Using the protected constructor to set _lenient to true
        // Since we are in the same package, we can access protected constructor
        StdDateFormat df = new StdDateFormat(TimeZone.getDefault(), Locale.getDefault(), Boolean.TRUE);
        assertTrue("isLenient should return true when _lenient is true", df.isLenient());
    }

    @Test
    public void testIsLenient_False() {
        // Using the protected constructor to set _lenient to false
        StdDateFormat df = new StdDateFormat(TimeZone.getDefault(), Locale.getDefault(), Boolean.FALSE);
        assertFalse("isLenient should return false when _lenient is false", df.isLenient());
    }
}
